import { v4 as uuidv4 } from 'uuid';
import { addDays, isAfter } from 'date-fns';
import { InviteRepository } from './repository';
import { EmailService } from '../email/service';
import { User } from '../users/model';
import { ForbiddenError, NotFoundError, BadRequestError } from '../errors';

const INVITE_EXPIRATION_DAYS = 7;

export class InviteService {
  constructor(
    private inviteRepo: InviteRepository,
    private emailService: EmailService,
  ) {}

  // Only admins can create invites
  async createInvite(requester: User, email: string) {
    if (!requester.isAdmin) {
      throw new ForbiddenError('Only admins can send invites');
    }

    // Validate email format (basic)
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      throw new BadRequestError('Invalid email address');
    }

    // Check if an active invite already exists for this email
    const existing = await this.inviteRepo.findActiveByEmail(email);
    if (existing) {
      throw new BadRequestError('An active invite already exists for this email');
    }

    const token = uuidv4();
    const expiresAt = addDays(new Date(), INVITE_EXPIRATION_DAYS);

    const invite = await this.inviteRepo.create({
      email,
      token,
      expiresAt,
      createdBy: requester.id,
      used: false,
    });

    // Send invitation email
    await this.emailService.sendInviteEmail(email, token, expiresAt);

    return invite;
  }

  // Retrieve an invite by token (used during acceptance)
  async getInviteByToken(token: string) {
    const invite = await this.inviteRepo.findByToken(token);
    if (!invite) {
      throw new NotFoundError('Invite not found');
    }

    if (invite.used) {
      throw new BadRequestError('Invite has already been used');
    }

    if (isAfter(new Date(), invite.expiresAt)) {
      throw new BadRequestError('Invite has expired');
    }

    return invite;
