import { v4 as uuidv4 } from 'uuid';
import { addDays, isAfter } from 'date-fns';
import { InviteRepository } from './repository';
import { EmailService } from '../email/service';
import { User } from '../users/model';

export interface Invite {
  id: string;
  email: string;
  token: string;
  expiresAt: Date;
  createdBy: string; // admin user id
  used: boolean;
}

export class InviteService {
  private repo: InviteRepository;
  private emailService: EmailService;

  constructor(repo: InviteRepository, emailService: EmailService) {
    this.repo = repo;
    this.emailService = emailService;
  }

  // Only admins can create invites
  async createInvite(admin: User, email: string): Promise<Invite> {
    if (!admin.isAdmin) {
      throw new Error('Only admins can send invites');
    }

    const token = uuidv4();
    const expiresAt = addDays(new Date(), 7);

    const invite: Invite = {
      id: uuidv4(),
      email,
      token,
      expiresAt,
      createdBy: admin.id,
      used: false,
    };

    await this.repo.save(invite);
    await this.emailService.sendInviteEmail(email, token, expiresAt);
    return invite;
  }

  async getInviteByToken(token: string): Promise<Invite | null> {
    const invite = await this.repo.findByToken(token);
    if (!invite) return null;
    if (invite.used) return null;
    if (isAfter(new Date(), invite.expiresAt)) return null;
    return invite;
  }

  // Mark an invite as used after successful registration
  async consumeInvite(token: string): Promise<void> {
    const invite = await this.repo.findByToken(token);
    if (!invite) {
      throw new Error('Invalid invite token');
    }
    if (invite.used) {
      throw new Error('Invite already used');
    }
    if (isAfter(new Date(), invite.expiresAt)) {
      throw new Error('Invite has expired');
    }
    invite.used = true;
    await this.repo.update(invite);
  }

  // Resend an existing invite (admin only)
  async resendInvite(admin: User, token: string): Promise<void> {
    if (!admin.isAdmin) {
      throw new Error('Only admins can resend invites');
    }
    const invite = await this.repo.findByToken(token);
    if (!invite) {
      throw new Error('Invite not found');
    }
    if (invite.used) {
      throw new Error('Cannot resend a used invite');
    }
